// app/api/chat/route.ts (Next.js App Router)
import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // key is read from ANTHROPIC_API_KEY, server only

export async function POST(req: Request) {
  const { conversationId, messageId, text } = await req.json();
  // (auth check: does this user own conversationId?)
  await db.insertUserMessageIfAbsent({ id: messageId, conversationId, text });
  const history = await db.loadHistory(conversationId); // trimmed on the server

  const t0 = Date.now();
  let ttftMs: number | null = null;
  const upstream = client.messages.stream(
    { model: MODEL, max_tokens: 1024, system: SYSTEM_PROMPT, messages: history },
    { signal: req.signal } // browser went away -> provider call is aborted too
  );

  const enc = new TextEncoder();
  let open = true; // false once the browser has closed the connection
  const body = new ReadableStream({
    async start(controller) {
      const send = (event: string, data: unknown) => {
        if (open) controller.enqueue(enc.encode("event: " + event + "\ndata: " + JSON.stringify(data) + "\n\n"));
      };
      try {
        for await (const ev of upstream) {
          if (ev.type === "content_block_delta" && ev.delta.type === "text_delta") {
            ttftMs ??= Date.now() - t0;
            send("delta", { text: ev.delta.text });
          }
        }
        const final = await upstream.finalMessage();
        await db.saveAssistantMessage({ conversationId, replyTo: messageId, message: final });
        send("done", { stopReason: final.stop_reason, usage: final.usage });
        log({ requestId: upstream.request_id, model: MODEL, ttftMs, totalMs: Date.now() - t0,
              stopReason: final.stop_reason, usage: final.usage });
      } catch (err) {
        const status = err instanceof Anthropic.APIError ? err.status : undefined;
        log({ requestId: upstream.request_id, model: MODEL, ttftMs, totalMs: Date.now() - t0, status, aborted: req.signal.aborted });
        send("error", { status }); // the partial text stays on the client, marked as failed
      } finally {
        if (open) controller.close();
      }
    },
    cancel() { open = false; },
  });

  return new Response(body, {
    headers: { "Content-Type": "text/event-stream", "Cache-Control": "no-cache" },
  });
}

// Reads an SSE body and calls onEvent(event, data) for every complete event.
async function readSSE(body, onEvent) {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buf = "";
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buf += decoder.decode(value, { stream: true }); // keeps half a letter for the next chunk
    let i;
    while ((i = buf.indexOf("\n\n")) !== -1) {      // blank line = end of one event
      const raw = buf.slice(0, i);
      buf = buf.slice(i + 2);
      let event = "message", data = "";
      for (const line of raw.split("\n")) {
        if (line.startsWith("event: ")) event = line.slice(7);
        else if (line.startsWith("data: ")) data += line.slice(6);
      }
      onEvent(event, JSON.parse(data));
    }
  }
}

