type ChatMessage = {
  id: string;                 // генерирует клиент, переживает retry
  role: "user" | "assistant";
  content: string;            // у стримящегося сообщения растёт
  status: Status;
  stopped?: boolean;          // пользователь нажал «Стоп»
  usage?: { input_tokens: number; output_tokens: number }; // из события done
