import { useRef, useState } from "react";

export function useBufferedText() {
  const [text, setText] = useState("");
  const pending = useRef("");
  const frame = useRef<number | null>(null);

  const flush = () => {
    frame.current = null;
    const chunk = pending.current;
    pending.current = "";
    if (chunk) setText((t) => t + chunk); // one React update per frame
  };

  const push = (delta: string) => {
    pending.current += delta;               // cheap: no render yet
    if (frame.current === null) frame.current = requestAnimationFrame(flush);
  };

  const finish = () => {                    // on "done" / "error": flush right away,
    if (frame.current !== null) cancelAnimationFrame(frame.current);
    flush();                                // rAF is paused in background tabs
  };

  return { text, push, finish };
}

const FENCE = String.fromCharCode(96).repeat(3); // three backticks

// Splits streamed markdown at blank lines, never inside a code block.
// Every block except the last is final and can be memoized.
function splitBlocks(md) {
  const blocks = [];
  let cur = [], inCode = false;
  for (const line of md.split("\n")) {
    if (line.trimStart().startsWith(FENCE)) inCode = !inCode;
    if (line === "" && !inCode) { if (cur.length) blocks.push(cur.join("\n")); cur = []; }
    else cur.push(line);
  }
  blocks.push(cur.join("\n"));
  return { blocks, inCode };
}

// The tail is still growing: close an open code block for rendering only.
const renderableTail = (tail, inCode) => (inCode ? tail + "\n" + FENCE : tail);

